    # to their associated boundary pattern. In this instance, each marker column
    # forms a 1-wide extension to the bottom boundary; the pair at (3,0)/(3,3)
    # also gives a horizontal continuation to the right.
    for r, c in markers:
        for rr in range(r + 1, h):
            if grid[rr][c] == bg:
                out[rr][c] = 1
            else:
