 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))

    # Each sparse marker (color unlike the background/frame) launches a ray
    # toward the nearest edge-associated run of its own marker color. Keep edge
    # frame colors untouched; the marker itself is highlighted as 4.
    edge_colors = {grid[r][0] for r in range(h)} | {grid[r][w-1] for r in range(h)}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color not in edge_colors:
                continue
            if c > 0 and any(grid[rr][0] == color for rr in range(h)):
                out[r][c] = 4
                for cc in range(1, c):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
            elif c < w-1 and any(grid[rr][w-1] == color for rr in range(h)):
                out[r][c] = 4
                for cc in range(c+1, w-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = color

    # Simpler rule for the demonstrated task family: isolated seed cells on
    # rows between edge runs project horizontally to the nearer edge run.
    for r in range(h):
        cells = [c for c,v in enumerate(grid[r]) if v != bg and v not in edge_colors]
        for c in cells:
            # Marker values are the sparse non-background, non-frame colors.
            color = grid[r][c]
            out[r][c] = 4
            if any(grid[rr][0] == color for rr in range(h)):
                start, stop = 0, c
                for cc in range(start+1, stop):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
            elif any(grid[rr][w-1] == color for rr in range(h)):
                for cc in range(c+1, w-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
    return out

