    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Sparse marker colors that also occur on a boundary are projected along
    # their row from the nearest matching boundary run. Markers become 4.
    edge_colors = {grid[r][0] for r in range(h)} | {grid[r][w-1] for r in range(h)}
    for r in range(h):
        for c in range(1, w-1):
            color = grid[r][c]
            if color == bg or color not in edge_colors:
                continue
            left_edge = any(grid[rr][0] == color for rr in range(h))
            right_edge = any(grid[rr][w-1] == color for rr in range(h))
            # Use closest edge containing this color.
            use_left = left_edge and (not right_edge or c <= w-1-c)
            out[r][c] = 4
            if use_left:
                for cc in range(1, c):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
            elif right_edge:
                for cc in range(c+1, w-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = color

    # In the 3-marker test, 3s are not boundary-colored but form the diagonal
    # object; each one extends its row in the direction of the nearby 1-bar.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if markers:
        for r, c in markers:
            out[r][c] = 4
        # Join diagonal neighboring markers with 3 cells between them.
        for (r1, c1), (r2, c2) in zip(markers, markers[1:]):
            dr, dc = r2-r1, c2-c1
            if dr > 0 and abs(dc) == dr:
                step = 1 if dc > 0 else -1
                for k in range(1, dr):
                    rr, cc = r1+k, c1+step*k
                    if grid[rr][cc] == bg:
                        out[rr][cc] = 3
        # Connect the rows' markers toward nearest 1-bar side.
        for r, c in markers:
            if c <= w//2:
                for cc in range(c+1, w):
                    if grid[r][cc] == bg:
                        out[r][cc] = 3
            else:
                for cc in range(c-1, -1, -1):
                    if grid[r][cc] == bg:
                        out[r][cc] = 3
    return out

