        others = [(rr, cc) for rr, cc in markers if rr != r]
        if others:
            rr, cc = min(others, key=lambda p: abs(p[0] - r))
            dc = 1 if cc > c else -1
            dr = 1 if rr > r else -1
            # Continue the marker ray along the same diagonal toward the edge.
