 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Recolor each isolated 3 marker to 4 and extend a 3-ray horizontally
    # toward the nearest edge rail of the grid.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in markers:
        out[r][c] = 4
        # Determine ray direction from its local diagonal continuation.
        same_row = sorted(cc for rr, cc in markers if rr == r)
        if len(same_row) > 1:
            lo, hi = same_row[0], same_row[-1]
            for cc in range(lo + 1, hi):
                if grid[r][cc] == background:
                    out[r][cc] = 3
            continue
        above = [(rr, cc) for rr, cc in markers if rr < r]
        below = [(rr, cc) for rr, cc in markers if rr > r]
        if below:
            next_r, next_c = min(below, key=lambda p: p[0] - r)
            direction = 1 if next_c > c else -1
        elif above:
            prev_r, prev_c = max(above, key=lambda p: p[0])
            direction = 1 if c > prev_c else -1
        else:
            direction = -1 if c <= w // 2 else 1
        cc = c + direction
        while 0 <= cc < w:
            if grid[r][cc] == background:
                out[r][cc] = 3
            cc += direction

    # The 1 edge runs provide long horizontal rays at their respective rows.
    for r in range(h):
        if any(v == 1 for v in grid[r]):
            for c in range(w):
                if grid[r][c] == background:
                    out[r][c] = 1
    return out
