    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # 3 markers are endpoints of horizontal 3-rays. They become 4; rays extend
    # toward the next matching row/edge structure, in the direction indicated
    # by the local diagonal arrangement.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in markers:
        out[r][c] = 4

    # Markers at left edge define inward rays to the next marker on that row.
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2 and min(cols) == 0:
            for c in range(1, max(cols)):
                if grid[r][c] == bg:
                    out[r][c] = 3

    # Isolated markers in the upper-left portion extend rightward; marker rows
    # with paired markers define a short horizontal segment; lower-left pattern
    # extends only between the repeated diagonal marker tracks.
    for r, c in markers:
        cols = [cc for rr, cc in markers if rr == r]
        if len(cols) > 1:
            continue
        if r == min((rr for rr, _ in markers), default=r):
            for cc in range(c + 1, w):
                if grid[r][cc] == bg:
                    out[r][cc] = 3

    # 1 edge bars extend across their entire row, as in the examples.
    for r in range(h):
        if 1 in grid[r]:
            for c in range(w):
                if grid[r][c] == bg:
                    out[r][c] = 1
    return out

