    # Convert the isolated seed cells to 4 and extend their local diagonal
    # strokes in color 3, retaining the original edge bars.
    for r, c in markers:
        out[r][c] = 4

    # Interpolate between markers on a diagonal, and thicken the diagonal by
    # one adjacent cell to match the 2-cell-wide lines in the demonstrations.
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr > 0 and abs(dc) == dr:
                step = 1 if dc > 0 else -1
                for k in range(1, dr):
                    rr, cc = r1 + k, c1 + step * k
                    for x, y in ((rr, cc), (rr, cc + step)):
                        if 0 <= x < h and 0 <= y < w and grid[x][y] == bg:
                            out[x][y] = 3
                break

    # The edge bars at opposite corners extend along their boundary rows.
    # Preserve their given partial runs and fill the corresponding row.
    for r in (0, h - 1):
        if 1 in grid[r]:
            for c in range(w):
                if grid[r][c] == bg:
                    out[r][c] = 1

