    for r, c in markers:
        rows.setdefault(r, []).append(c)

    # Mark the sparse endpoints and fill their short joining/ray segments.
    for r, c in markers:
        out[r][c] = 4
    for r, cols in rows.items():
        cols.sort()
        if len(cols) > 1:
            for c in range(cols[0] + 1, cols[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 3
        else:
            c = cols[0]
            if c == 0:
                # Edge endpoint casts toward its paired seed.
                target = min((cc for rr, cc in markers if rr == r and cc > c), default=c)
                for cc in range(c + 1, target):
                    if grid[r][cc] == bg:
                        out[r][cc] = 3
            elif r == min(rows):
                # Isolated top seed extends rightward to the opposite rail.
                for cc in range(c + 1, w):
                    if grid[r][cc] == bg:
                        out[r][cc] = 3

    # The diagonal sequence has two parallel 3 strands. Fill the lattice cells
    # between the paired marker rows, preserving all seed points and bars.
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr > 0 and abs(dc) == dr:
                step = 1 if dc > 0 else -1
                for k in range(1, dr):
                    rr, cc = r1 + k, c1 + step * k
                    if grid[rr][cc] == bg:
                        out[rr][cc] = 3
                break

    # Extend the top-right and bottom-left 1 rails fully across their rows.
    for r in (0, h - 1):
        if 1 in grid[r]:
            for c in range(w):
                if grid[r][c] == bg:
                    out[r][c] = 1
    return out
