    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def runs_on_edge(values):
        runs = []
        start = 0
        while start < len(values):
            color = values[start]
            end = start + 1
            while end < len(values) and values[end] == color:
                end += 1
            if color != background:
                runs.append((color, start, end - 1))
            start = end
        return runs

    # Find equal-length, same-color bars on opposite edges. Their offset maps
    # a seed's position beside one bar to the corresponding position beside
    # the opposite bar.
    candidates = []
    for orientation in ("vertical", "horizontal"):
        if orientation == "vertical":
            edge_a = runs_on_edge(grid[0])
            edge_b = runs_on_edge(grid[-1])
        else:
            edge_a = runs_on_edge([grid[r][0] for r in range(h)])
            edge_b = runs_on_edge([grid[r][-1] for r in range(h)])
        for color_a, a0, a1 in edge_a:
            for color_b, b0, b1 in edge_b:
                if color_a == color_b and a1 - a0 == b1 - b0:
                    candidates.append((a1 - a0 + 1, color_a, orientation,
                                       (a0, a1), (b0, b1)))

    if not candidates:
        return out
    _, rail_color, orientation, interval_a, interval_b = max(candidates)

    # The sparse non-background, non-rail color marks the ray endpoints.
    seed_counts = {color: count for color, count in counts.items()
                   if color not in (background, rail_color)}
    if not seed_counts:
        return out
    seed_color = min(seed_counts, key=lambda color: seed_counts[color])
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == seed_color]

    a0, a1 = interval_a
    b0, b1 = interval_b
    # For each seed in either rail interval, cast a ray from the seed toward
    # its nearby edge bar, and draw the translated full ray at the other bar.
    for r, c in seeds:
        t = c if orientation == "vertical" else r
        if a0 <= t <= a1:
            mate = b0 + (t - a0)
            source_side = "top" if orientation == "vertical" else "left"
        elif b0 <= t <= b1:
            mate = a0 + (t - b0)
            source_side = "bottom" if orientation == "vertical" else "right"
        else:
            continue

        if orientation == "vertical":
            # Source ray runs from its edge toward the seed.
            rows = range(1, r) if source_side == "top" else range(r + 1, h - 1)
            for rr in rows:
                if grid[rr][c] == background:
                    out[rr][c] = seed_color
            # Translated companion spans the channel between the two bars.
            for rr in range(1, h - 1):
                if grid[rr][mate] == background:
                    out[rr][mate] = seed_color
        else:
            cols = range(1, c) if source_side == "left" else range(c + 1, w - 1)
            for cc in cols:
                if grid[r][cc] == background:
                    out[r][cc] = seed_color
            for cc in range(1, w - 1):
                if grid[mate][cc] == background:
                    out[mate][cc] = seed_color

    for r, c in seeds:
        out[r][c] = 4
    return out

