        result = []
        i = 0
        while i < len(values):
            color = values[i]
            j = i + 1
            while j < len(values) and values[j] == color:
                j += 1
            if color != background:
                result.append((color, i, j - 1))
            i = j
        return result

    # Locate matching bars on opposite borders. A bar pair's matching positions
    # are related by the constant offset between their intervals.
    pairs = []
    borders = (
        ("vertical", edge_runs(grid[0]), edge_runs(grid[-1])),
        ("horizontal",
         edge_runs([grid[r][0] for r in range(h)]),
         edge_runs([grid[r][-1] for r in range(h)])),
    )
    for orientation, first_runs, opposite_runs in borders:
        for color_a, a0, a1 in first_runs:
            for color_b, b0, b1 in opposite_runs:
                if color_a == color_b and a1 - a0 == b1 - b0:
                    pairs.append((a1 - a0 + 1, orientation, color_a,
                                  a0, a1, b0, b1))
    if not pairs:
        return out

