             if grid[r][c] == seed_color]

    for r, c in seeds:
        t = c if orientation == "vertical" else r
        if a0 <= t <= a1:
            mate = b0 + (t - a0)
            source_is_first = True
        elif b0 <= t <= b1:
            mate = a0 + (t - b0)
            source_is_first = False
        else:
            # A dot not aligned with either bar still gets highlighted.
            out[r][c] = 4
            continue

