    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Identify edge markers on opposing borders. Equal runs of a color denote
    # matching endpoints of several parallel rays.
    def edge_marks(values):
        return [(i, color) for i, color in enumerate(values) if color != background]

    # Most tasks here use corner-to-corner same-color edge bars as rails.
    top_marks = edge_marks(grid[0])
    bottom_marks = edge_marks(grid[-1])
    left_marks = edge_marks([grid[r][0] for r in range(h)])
    right_marks = edge_marks([grid[r][-1] for r in range(h)])

    # Sparse marker color is the least frequent non-background color.
    colors = [c for c in counts if c != background]
    if not colors:
        return out
    marker_color = min(colors, key=lambda c: counts[c])
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]

    # In the horizontal-edge case, the matching edge bars frame a 2-cell-wide
    # horizontal ray pair. Each seed paints toward the nearest matching edge
    # in its row; diagonal displacement of the seeds determines the corridor.
    if top_marks and bottom_marks and top_marks[0][1] == bottom_marks[0][1]:
        top_left = min(c for c, _ in top_marks)
        top_right = max(c for c, _ in top_marks)
        bot_left = min(c for c, _ in bottom_marks)
        bot_right = max(c for c, _ in bottom_marks)
        offset = top_left - bot_left
        for r, c in seeds:
            out[r][c] = 4
            # A marker near the left portion emits rightward to its paired rail.
            if bot_left <= c <= bot_right:
                mate = c + offset
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == background:
                        out[rr][c] = marker_color
                if 0 <= mate < w:
                    for rr in range(1, h - 1):
                        if grid[rr][mate] == background:
                            out[rr][mate] = marker_color
            elif top_left <= c <= top_right:
                mate = c - offset
                for rr in range(1, r):
                    if grid[rr][c] == background:
                        out[rr][c] = marker_color
                if 0 <= mate < w:
                    for rr in range(1, h - 1):
                        if grid[rr][mate] == background:
                            out[rr][mate] = marker_color

    # The seed endpoints are always recolored 4.
    for r, c in seeds:
        out[r][c] = 4
    return out
